//! Driver for the Semtech SX1276/77/78/79 (HopeRF RFM95/96/97/98) in
//! **FSK/OOK packet mode** (receive side) and **LoRa**.
//!
//! The register map lives in [`registers`] and is generated by the
//! `device-driver` crate; [`Sx1276`] is the small hand-written layer on top:
//! reset, configure, receive. The generated [`registers::Registers`] is
//! reachable through [`Sx1276::registers`] for anything the high level API
//! does not cover. LoRa has its own register map ([`lora_registers`]) and driver
//! ([`lora::Lora`]); switch between them with `release()`.
//!
//! Chip behaviour worth knowing (datasheet Rev. 4, sections 4.2.6/4.2.7, Table 24):
//! * AGC and AFC only run at receiver (re)start **and only if `RxTrigger`
//!   selects an event**. With `RxTrigger = None` neither runs, so the gain stays
//!   wherever it started and strong or off-frequency signals are lost.
//!   [`Sx1276::init`] therefore uses the preamble trigger.
//! * `RxReady` is set in Rx only after RSSI, AGC and AFC have run, i.e. with a
//!   preamble trigger, after a preamble arrives. Neither it nor `ModeReady` can
//!   be relied on to say "receiving"; in practice the chip was seen sitting in
//!   FSRx with the PLL locked and no ready flag, yet receiving.
//!   [`Sx1276::start_rx`] therefore accepts that state.
//! * The hardware CRC is CCITT with init 0x1D0F. Transmitters using any other
//!   CRC must run with `hw_crc: false` and are not checked at all.
#![no_std]

pub mod lora;
pub mod lora_registers;
#[cfg(feature = "qcp")]
pub mod qcp;
pub mod registers;

use device_driver::{BufferInterface, BufferInterfaceError, RegisterInterface};
use embedded_hal::delay::DelayNs;
use embedded_hal::digital::OutputPin;
use embedded_hal::spi::{Operation, SpiDevice};

pub use registers::{Mode, RxBwMantissa, RxTrigger};

/// Crystal frequency of the SX1276 (Hz).
const FXOSC: u64 = 32_000_000;

/// Largest payload accepted. The FIFO is 66 bytes and also holds the length byte.
pub const MAX_PAYLOAD: usize = 64;

/// Silicon version of every SX1276/77/78/79.
const EXPECTED_VERSION: u8 = 0x12;

/// Everything that can go wrong.
#[derive(Debug)]
pub enum Error<E> {
    /// SPI bus error.
    Spi(E),
    /// Reset pin error.
    Pin,
    /// `RegVersion` did not read 0x12: wiring problem or wrong chip.
    BadVersion(u8),
    /// Radio never signalled `ModeReady` (or PLL lock) after a mode switch.
    ModeTimeout { target: Mode, mode: Mode, irq1: u8 },
    /// Image calibration never finished.
    ImageCalTimeout,
}

impl<E> From<E> for Error<E> {
    fn from(e: E) -> Self {
        Error::Spi(e)
    }
}

/// SPI transport for [`registers::Registers`]. Register access sets bit 7 of
/// the address byte for writes; the FIFO is a burst on address 0.
pub struct SpiInterface<SPI> {
    spi: SPI,
}

impl<SPI> SpiInterface<SPI> {
    pub fn new(spi: SPI) -> Self {
        Self { spi }
    }

    /// Give the SPI device back.
    pub fn into_inner(self) -> SPI {
        self.spi
    }
}

impl<SPI: SpiDevice> RegisterInterface for SpiInterface<SPI> {
    type Error = SPI::Error;
    type AddressType = u8;

    fn write_register(&mut self, address: u8, _size_bits: u32, data: &[u8]) -> Result<(), Self::Error> {
        self.spi
            .transaction(&mut [Operation::Write(&[address | 0x80]), Operation::Write(data)])
    }

    fn read_register(&mut self, address: u8, _size_bits: u32, data: &mut [u8]) -> Result<(), Self::Error> {
        self.spi
            .transaction(&mut [Operation::Write(&[address & 0x7F]), Operation::Read(data)])
    }
}

impl<SPI: SpiDevice> BufferInterfaceError for SpiInterface<SPI> {
    type Error = SPI::Error;
}

impl<SPI: SpiDevice> BufferInterface for SpiInterface<SPI> {
    type AddressType = u8;

    fn write(&mut self, address: u8, buf: &[u8]) -> Result<usize, Self::Error> {
        self.spi
            .transaction(&mut [Operation::Write(&[address | 0x80]), Operation::Write(buf)])?;
        Ok(buf.len())
    }

    fn flush(&mut self, _address: u8) -> Result<(), Self::Error> {
        Ok(())
    }

    fn read(&mut self, address: u8, buf: &mut [u8]) -> Result<usize, Self::Error> {
        self.spi
            .transaction(&mut [Operation::Write(&[address & 0x7F]), Operation::Read(buf)])?;
        Ok(buf.len())
    }
}

/// RF/modem settings.
pub struct Config<'a> {
    /// Carrier frequency in Hz.
    pub frequency_hz: u32,
    /// Bit rate in bit/s.
    pub bitrate_bps: u32,
    /// Frequency deviation in Hz.
    pub fdev_hz: u32,
    /// Channel filter bandwidth, also used for the AFC: `Fxosc / (mantissa * 2^(exponent + 2))`.
    /// Must cover `bitrate + 2 * fdev` plus crystal error on both ends.
    pub rx_bw: (RxBwMantissa, u8),
    /// Sync word, 1..=8 bytes. The transmitter must use the same one.
    pub sync_word: &'a [u8],
    /// Preamble pattern: `true` = 0x55, `false` = 0xAA.
    pub preamble_is_0x55: bool,
    /// Use the hardware CRC (CCITT, init 0x1D0F). Leave off when the transmitter
    /// uses a different CRC; it is then not checked at all.
    pub hw_crc: bool,
    /// Automatic gain control. When `false`, `lna_gain` is a fixed gain.
    pub agc_auto: bool,
    /// Fixed LNA gain, 1 (maximum) ..= 6 (-48 dB; steps are 0, -6, -12, -24, -36, -48 dB).
    /// Only used when `agc_auto` is `false`.
    pub lna_gain: u8,
}

/// SX1276 in FSK/OOK packet mode. `SPI` must assert chip select for the
/// length of each transaction (e.g. `embedded_hal_bus::spi::ExclusiveDevice`).
pub struct Sx1276<SPI: SpiDevice, RST> {
    dev: registers::Registers<SpiInterface<SPI>>,
    rst: RST,
}

impl<SPI: SpiDevice, RST: OutputPin> Sx1276<SPI, RST> {
    pub fn new(spi: SPI, rst: RST) -> Self {
        Self { dev: registers::Registers::new(SpiInterface::new(spi)), rst }
    }

    /// Give the SPI device and reset pin back, e.g. to switch to [`lora::Lora`].
    pub fn release(self) -> (SPI, RST) {
        (self.dev.interface.into_inner(), self.rst)
    }

    /// Direct access to the generated register map.
    pub fn registers(&mut self) -> &mut registers::Registers<SpiInterface<SPI>> {
        &mut self.dev
    }

    fn set_mode(&mut self, mode: Mode) -> Result<(), SPI::Error> {
        self.dev.op_mode().modify(|r| {
            r.set_long_range_mode(false);
            r.set_modulation_type(registers::ModulationType::Fsk);
            r.set_mode(mode);
        })
    }

    /// Request `target` and wait for `ModeReady`.
    fn enter_mode(&mut self, target: Mode) -> Result<(), Error<SPI::Error>> {
        self.set_mode(target)?;
        let mut irq1 = 0;
        for _ in 0..10_000 {
            let f = self.dev.irq_flags_1().read()?;
            irq1 = <[u8; 1]>::from(f)[0];
            if f.mode_ready() {
                return Ok(());
            }
        }
        let mode = self.dev.op_mode().read()?.mode();
        Err(Error::ModeTimeout { target, mode, irq1 })
    }

    /// Hardware-reset the module, verify it answers and configure FSK mode.
    /// Leaves the radio in standby.
    pub fn init(&mut self, delay: &mut impl DelayNs, cfg: &Config<'_>) -> Result<(), Error<SPI::Error>> {
        // Reset: pull low >100 us, release, wait >=5 ms.
        self.rst.set_low().map_err(|_| Error::Pin)?;
        delay.delay_ms(1);
        self.rst.set_high().map_err(|_| Error::Pin)?;
        delay.delay_ms(10);

        let version = self.dev.version().read()?.value();
        if version != EXPECTED_VERSION {
            return Err(Error::BadVersion(version));
        }

        // The LongRangeMode bit can only be changed in Sleep.
        self.set_mode(Mode::Sleep)?;
        delay.delay_ms(2);
        self.enter_mode(Mode::Standby)?;

        // Bit rate: BitRate = Fxosc / value.
        self.dev.bitrate().write(|r| r.set_value((FXOSC / cfg.bitrate_bps as u64) as u16))?;
        // Fdev = value * Fstep, Fstep = Fxosc / 2^19.
        self.dev.fdev().write(|r| r.set_value((((cfg.fdev_hz as u64) << 19) / FXOSC) as u16))?;
        // Carrier = value * Fstep (24 bits).
        self.dev.frf().write(|r| r.set_value((((cfg.frequency_hz as u64) << 19) / FXOSC) as u32))?;

        // Image calibration for the band we are tuned to: start, then wait until
        // it is no longer running. Must happen in standby after Frf is set.
        self.dev.image_cal().modify(|r| r.set_image_cal_start(true))?;
        let mut done = false;
        for _ in 0..10_000 {
            if !self.dev.image_cal().read()?.image_cal_running() {
                done = true;
                break;
            }
        }
        if !done {
            return Err(Error::ImageCalTimeout);
        }

        // Never transmit by accident: RFO pin, minimum power.
        self.dev.pa_config().modify(|r| {
            r.set_pa_select(false);
            r.set_max_power(0);
            r.set_output_power(0);
        })?;

        // LNA: gain (ignored by the chip while AGC is on), boost on for the HF band.
        self.dev.lna().modify(|r| {
            r.set_lna_gain(match cfg.lna_gain.clamp(1, 6) {
                1 => registers::LnaGain::G1,
                2 => registers::LnaGain::G2,
                3 => registers::LnaGain::G3,
                4 => registers::LnaGain::G4,
                5 => registers::LnaGain::G5,
                _ => registers::LnaGain::G6,
            });
            r.set_lna_boost_hf(0b11);
        })?;

        // AFC on, AGC optional, measured on the packet's preamble.
        self.dev.rx_config().modify(|r| {
            r.set_afc_auto_on(true);
            r.set_agc_auto_on(cfg.agc_auto);
            r.set_rx_trigger(RxTrigger::PreambleDetect);
        })?;
        let (mantissa, exponent) = cfg.rx_bw;
        self.dev.rx_bw().modify(|r| {
            r.set_mantissa(mantissa);
            r.set_exponent(exponent);
        })?;
        self.dev.afc_bw().modify(|r| {
            r.set_mantissa(match mantissa {
                RxBwMantissa::M16 => registers::AfcBwMantissa::M16,
                RxBwMantissa::M20 => registers::AfcBwMantissa::M20,
                RxBwMantissa::M24 => registers::AfcBwMantissa::M24,
                RxBwMantissa::Reserved3 => registers::AfcBwMantissa::Reserved3,
            });
            r.set_exponent(exponent);
        })?;

        // Preamble detector on, 2 bytes, tolerance 10 chip errors.
        self.dev.preamble_detect().modify(|r| {
            r.set_preamble_detector_on(true);
            r.set_preamble_detector_size(1);
            r.set_preamble_detector_tolerance(0x0A);
        })?;
        self.dev.preamble_size().write(|r| r.set_value(3))?;

        // Sync word.
        let n = cfg.sync_word.len().clamp(1, 8);
        self.dev.sync_config().modify(|r| {
            r.set_auto_restart_rx_mode(registers::AutoRestartRxMode::OnWithPllRelock);
            r.set_preamble_polarity_55(cfg.preamble_is_0x55);
            r.set_sync_on(true);
            r.set_sync_size(n as u8 - 1);
        })?;
        for (i, &b) in cfg.sync_word[..n].iter().enumerate() {
            self.dev.sync_value(i).write(|r| r.set_value(b))?;
        }

        // Packet: variable length, no DC-free coding, optional hardware CRC with
        // auto-clear (bad-CRC packets are dropped, PayloadReady stays low).
        self.dev.packet_config_1().modify(|r| {
            r.set_variable_length(true);
            r.set_dc_free(registers::DcFree::None);
            r.set_crc_on(cfg.hw_crc);
            r.set_crc_auto_clear_off(false);
        })?;
        self.dev.packet_config_2().modify(|r| {
            r.set_packet_mode(true);
            r.set_payload_length_msb(0);
        })?;
        // In variable-length receive this is the maximum accepted length.
        self.dev.payload_length().write(|r| r.set_value(MAX_PAYLOAD as u8))?;
        self.dev.fifo_thresh().modify(|r| {
            r.set_tx_start_fifo_not_empty(true);
            r.set_fifo_threshold(0x0F);
        })?;

        // DIO0 = PayloadReady in RX (0b00).
        self.dev.dio_mapping_1().modify(|r| r.set_dio_0(0))?;
        Ok(())
    }

    /// Enter continuous receive via FSRx: request FSRx, wait for PLL lock,
    /// then request Rx.
    pub fn start_rx(&mut self) -> Result<(), Error<SPI::Error>> {
        self.set_mode(Mode::FsRx)?;
        let mut locked = false;
        let mut irq1 = 0;
        for _ in 0..10_000 {
            let f = self.dev.irq_flags_1().read()?;
            irq1 = <[u8; 1]>::from(f)[0];
            if f.pll_lock() {
                locked = true;
                break;
            }
        }
        if !locked {
            let mode = self.dev.op_mode().read()?.mode();
            return Err(Error::ModeTimeout { target: Mode::FsRx, mode, irq1 });
        }

        self.set_mode(Mode::Rx)?;
        for _ in 0..10_000 {
            let f = self.dev.irq_flags_1().read()?;
            irq1 = <[u8; 1]>::from(f)[0];
            if f.mode_ready() || f.rx_ready() {
                return Ok(());
            }
        }
        // See the crate docs: FSRx with the PLL locked is accepted.
        let mode = self.dev.op_mode().read()?.mode();
        if self.dev.irq_flags_1().read()?.pll_lock() && matches!(mode, Mode::FsRx | Mode::Rx) {
            return Ok(());
        }
        Err(Error::ModeTimeout { target: Mode::Rx, mode, irq1 })
    }

    /// True if a complete packet is waiting in the FIFO (CRC-valid when the
    /// hardware CRC is on).
    pub fn payload_ready(&mut self) -> Result<bool, Error<SPI::Error>> {
        let f = self.dev.irq_flags_2().read()?;
        if f.fifo_overrun() {
            // Writing 1 clears the sticky overrun flag and flushes the FIFO.
            self.dev.irq_flags_2().write(|r| r.set_fifo_overrun(true))?;
        }
        Ok(f.payload_ready())
    }

    /// Read one packet from the FIFO into `buf`; returns the payload length
    /// (clamped to `buf.len()` if the packet was longer).
    pub fn read_packet(&mut self, buf: &mut [u8]) -> Result<usize, Error<SPI::Error>> {
        // Variable-length format: length byte first. The FIFO is a true queue,
        // so separate bursts continue where the previous one stopped.
        let mut len = [0u8];
        self.dev.fifo().read(&mut len)?;
        let total = (len[0] as usize).min(MAX_PAYLOAD);
        let keep = total.min(buf.len());
        if keep > 0 {
            self.dev.fifo().read(&mut buf[..keep])?;
        }
        // Drain whatever did not fit so the FIFO is empty again.
        let mut scratch = [0u8; MAX_PAYLOAD];
        if total > keep {
            self.dev.fifo().read(&mut scratch[..total - keep])?;
        }
        Ok(keep)
    }

    /// Current operating mode.
    pub fn mode(&mut self) -> Result<Mode, Error<SPI::Error>> {
        Ok(self.dev.op_mode().read()?.mode())
    }

    /// Current RSSI in dBm (valid while receiving).
    pub fn rssi_dbm(&mut self) -> Result<i16, Error<SPI::Error>> {
        Ok(-(self.dev.rssi_value().read()?.value() as i16) / 2)
    }
}
